  const r2 = addLine(r.value, { sku: 'STICKER', qty: 100, discountPercent: 10 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 10);
});

test('addLine uses explicit 0 discount over tier discount', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }]
  });

  // C-003 is silver tier (2.5%), but explicitly set to 0
  const r2 = addLine(r.value, { sku: 'STICKER', qty: 100, discountPercent: 0 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 0);
});

test('invoiceTotals calculates correctly with tier discounts', () => {
  // C-001 (gold tier = 5%)
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }
    ]
  });

  const totals = invoiceTotals(r.value);
  // Subtotal: 5 * 8500 = 42500
  // Discount: 42500 * 5% = 2125
  // Total: 42500 - 2125 = 40375
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 2125);
  assert.equal(totals.total, 40375);
});

test('lineVAT calculates VAT on line amount after discount', () => {
  // Amount: 8500, Discount: 0, After discount: 8500, VAT 21%: 1785
  assert.equal(lineVAT({ qty: 1, unitPrice: 8500, discountPercent: 0, vatRate: 21 }), 1785);
  // Amount: 42500, Discount: 2125 (5%), After discount: 40375, VAT 21%: 8478.75 = 8479 (rounded)
  assert.equal(lineVAT({ qty: 5, unitPrice: 8500, discountPercent: 5, vatRate: 21 }), 8479);
});

test('lineVAT handles 0% VAT', () => {
  assert.equal(lineVAT({ qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 0 }), 0);
});

test('lineVAT handles 9% VAT', () => {
  // Amount: 5000, VAT 9%: 450
  assert.equal(lineVAT({ qty: 100, unitPrice: 50, discountPercent: 0, vatRate: 9 }), 450);
});

test('lineVAT clamps at 0', () => {
  const result = lineVAT({ qty: 1, unitPrice: 100, discountPercent: 100, vatRate: 21 });
  assert.ok(result >= 0, 'lineVAT should never be negative');
});

test('invoiceTotals includes VAT', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 }
    ]
  });

  const totals = invoiceTotals(r.value);
  // DES-HOUR: 5 * 8500 = 42500, no discount, VAT 21%: 8925
  // Total: 42500 + 8925 = 51425
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 8925);
  assert.equal(totals.total, 51425);
});

test('invoiceTotals calculates total with discount and VAT', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 }
    ]
  });

  const totals = invoiceTotals(r.value);
  // DES-HOUR: 5 * 8500 = 42500
  // Discount: 42500 * 5% = 2125
  // After discount: 40375
  // VAT: 40375 * 21% = 8478.75 = 8479
  // Total: 42500 - 2125 + 8479 = 48854
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 2125);
  assert.equal(totals.vat, 8479);
  assert.equal(totals.total, 48854);
});

test('invoiceTotals with multiple lines and different VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 100, discountPercent: 0 }
    ]
  });

  const totals = invoiceTotals(r.value);
  // DES-HOUR: 5 * 8500 = 42500, VAT 21%: 8925
  // PRINT-A4: 100 * 37 = 3700, VAT 9%: 333
  // Subtotal: 46200
  // Total VAT: 9258
  // Total: 55458
  assert.equal(totals.subtotal, 46200);
  assert.equal(totals.vat, 9258);
  assert.equal(totals.total, 55458);
});

test('invoiceTotals with VAT-exempt items', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 0 }
    ]
  });

  const totals = invoiceTotals(r.value);
  // WORKSHOP-DAY: 60000, VAT 0%: 0
  // Total: 60000
  assert.equal(totals.subtotal, 60000);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 60000);
});

test('invoiceTotals clamps total at 0', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 1,
        unitPrice: 100,
        discountPercent: 100,
        vatRate: 21
      }
    ]
  };

  const totals = invoiceTotals(invoice);
  // After 100% discount, total is 0 (clamped)
  assert.equal(totals.total, 0);
  assert.ok(totals.total >= 0, 'total should never be negative');
});

