test('renderInvoiceText has consistent line structure', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
      { sku: 'STICKER', qty: 100, discountPercent: 0 }
    ]
  });

  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  // Check structure:
  // Line 0: DRAFT
  assert.equal(lines[0], 'DRAFT');
  // Line 1: Customer name
  assert.equal(lines[1], 'Northwind Studio');
  // Line 2: Empty line
  assert.equal(lines[2], '');
  // Lines 3-7: Invoice items with VAT lines
  assert.ok(lines[3].includes('Design work'), 'First item');
  assert.ok(lines[4].includes('21% VAT'), 'First item VAT');
  assert.ok(lines[5].includes('Sticker sheet'), 'Second item');
  assert.ok(lines[6].includes('21% VAT'), 'Second item VAT');
