    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }
    ]
  });

  const totals = invoiceTotals(r.value);
  // DES-HOUR: 5 * 8500 = 42500 (C-001 is gold tier with 5% discount)
  // Discount: 42500 * 5% = 2125 (tier discount applied since not explicit)
  // After discount: 40375
  // VAT 21%: 40375 * 21% = 8478.75 = 8479
  // Total: 42500 - 2125 + 8479 = 48854
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 2125);
  assert.equal(totals.vat, 8479);
  assert.equal(totals.total, 48854);
});

test('invoiceTotals with multiple lines and different VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 100, discountPercent: 0 }
    ]
  });

  const totals = invoiceTotals(r.value);
  // DES-HOUR: 5 * 8500 = 42500, VAT 21%: 8925
  // PRINT-A4: 100 * 37 = 3700, VAT 9%: 333
  // Subtotal: 46200
  // Total VAT: 9258
  // Total: 55458
  assert.equal(totals.subtotal, 46200);
  assert.equal(totals.vat, 9258);
  assert.equal(totals.total, 55458);
});

test('invoiceTotals with VAT-exempt items', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 0 }
    ]
  });

  const totals = invoiceTotals(r.value);
  // WORKSHOP-DAY: 60000, VAT 0%: 0
  // Total: 60000
  assert.equal(totals.subtotal, 60000);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 60000);
});

test('invoiceTotals clamps total at 0', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 1,
        unitPrice: 100,
        discountPercent: 100,
        vatRate: 21
      }
    ]
  };

  const totals = invoiceTotals(invoice);
  // After 100% discount, total is 0 (clamped)
  assert.equal(totals.total, 0);
  assert.ok(totals.total >= 0, 'total should never be negative');
});

