  assert.equal(lineVAT({ qty: 1, unitPrice: 8500, discountPercent: 0, vatRate: 21 }), 1785);
  // Amount: 42500, Discount: 2125 (5%), After discount: 40375, VAT 21%: 8478.75 = 8479 (rounded)
  assert.equal(lineVAT({ qty: 5, unitPrice: 8500, discountPercent: 5, vatRate: 21 }), 8479);
});

