test('invoiceTotals calculates correctly with tier discounts', () => {
  // C-001 (gold tier = 5%)
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }
    ]
  });

  const totals = invoiceTotals(r.value);
  // Subtotal: 5 * 8500 = 42500
  // Discount: 42500 * 5% = 2125
  // After discount: 40375
  // VAT 21%: 40375 * 21% = 8478.75 = 8479
  // Total: 42500 - 2125 + 8479 = 48854
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 2125);
  assert.equal(totals.vat, 8479);
  assert.equal(totals.total, 48854);
});

test('lineVAT calculates VAT on line amount after discount', () => {
  // Amount: 8500, Discount: 0, After discount: 8500, VAT 21%: 1785
  assert.equal(lineVAT({ qty: 1, unitPrice: 8500, discountPercent: 0, vatRate: 21 }), 1785);
  // Amount: 42500, Discount: 2125 (5%), After discount: 40375, VAT 21%: 8478.75 = 8479 (rounded)
  assert.equal(lineVAT({ qty: 5, unitPrice: 8500, discountPercent: 5, vatRate: 21 }), 8479);
});

test('lineVAT handles 0% VAT', () => {
  assert.equal(lineVAT({ qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 0 }), 0);
});

test('lineVAT handles 9% VAT', () => {
  // Amount: 5000, VAT 9%: 450
  assert.equal(lineVAT({ qty: 100, unitPrice: 50, discountPercent: 0, vatRate: 9 }), 450);
});

test('lineVAT clamps at 0', () => {
  const result = lineVAT({ qty: 1, unitPrice: 100, discountPercent: 100, vatRate: 21 });
  assert.ok(result >= 0, 'lineVAT should never be negative');
});

